class Acceptor:
    def __init__(self, store):
        self.store = store  # durable: must survive crash
        self.min_promise = store.load("promise", 0)
        self.acc_ballot = store.load("acc_ballot", 0)
        self.acc_value = store.load("acc_value", None)

    def on_prepare(self, n):
        if n > self.min_promise:
            self.min_promise = n
            self.store.fsync("promise", n)  # before reply
            return ("promise", self.acc_ballot, self.acc_value)
        return ("reject", self.min_promise)

    def on_accept(self, n, v):
        if n >= self.min_promise:
            self.min_promise = n
            self.acc_ballot, self.acc_value = n, v
            self.store.fsync_all(n, v)  # before reply
            return "accepted"
        return ("reject", self.min_promise)

def pick_value(promises, own):
    # promises: list of (acc_ballot, acc_value)
    seen = [(b, v) for b, v in promises if v is not None]
    if not seen:
        return own
    return max(seen, key=lambda t: t[0])[1]  # highest ballot wins
